// 瞄准角钳制在 ±80°，线性映射到 8 列之一
function angleToCol(angle) {
  const clamped = Math.max(-80, Math.min(80, angle));
  const t = (clamped + 80) / 160;
  return Math.min(COLS - 1, Math.floor(t * COLS));
}
// 挂在该列最低泡泡之下；空列顶到天花板，列满返回 null（判负）
function findAttachCell(grid, col) {
  for (let r = ROWS - 1; r >= 0; r--) {
    if (grid[r][col]) {
      if (r + 1 >= ROWS) return null;
      return { row: r + 1, col };
    }
  }
  return { row: 0, col };
}

function findFloating(grid) {
  const anchored = new Set();
  const queue = [];
  for (let c = 0; c < COLS; c++) {          // 顶行泡泡是天然锚点
    if (grid[0][c]) {
      anchored.add(`0,${c}`);
      queue.push([0, c]);
    }
  }
  while (queue.length > 0) {                // 八向 BFS 标记所有锚定泡泡
    const [r, c] = queue.shift();
    for (const [nr, nc] of neighbors(r, c)) {
      if (nr < 0 || nr >= ROWS || nc < 0 || nc >= COLS) continue;
      const key = `${nr},${nc}`;
      if (anchored.has(key)) continue;
      if (grid[nr][nc]) {
        anchored.add(key);
        queue.push([nr, nc]);
      }
    }
  }
  // 未被锚定的泡泡即悬空：整片下落、每颗 20 分
}
